package com.nova.engine;

import org.json.JSONArray;
import org.json.JSONObject;
import java.io.File;
import java.util.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** NovaScript mobile runtime, supported grammar is documented in README. */
final class NovaScriptRuntime {
    interface Logger { void line(String text, boolean error); void changed(); }
    private final File projectDir,sceneFile; private final Logger logger;
    private volatile boolean running; private Thread thread; private JSONObject sceneCache; private long lastPersist;
    private final Set<String> reported=new HashSet<>();
    private static final int MAX_STEPS=10000;
    NovaScriptRuntime(File dir,Logger logger){projectDir=dir;sceneFile=new File(dir,"scene.nscn");this.logger=logger;}
    synchronized void start(){if(running)return;running=true;thread=new Thread(this::loop,"NovaScriptRuntime");thread.start();}
    synchronized void stop(){running=false;if(thread!=null)thread.interrupt();try{flush();}catch(Exception e){logger.line("save: "+e.getMessage(),true);}}
    boolean isRunning(){return running;}
    private void loop(){Map<String,Program> programs=new LinkedHashMap<>();try{long previous=System.nanoTime();while(running){long now=System.nanoTime();float dt=Math.max(.001f,Math.min(.05f,(now-previous)/1_000_000_000f));previous=now;reload(programs);for(Program p:new ArrayList<>(programs.values())){if(p.start!=null&&!p.started){p.started=true;run(p,p.start,dt);}if(p.update!=null)run(p,p.update,dt);}physicsStep(dt);Thread.sleep(16);}}catch(InterruptedException ignored){Thread.currentThread().interrupt();}catch(Exception e){logger.line("runtime: "+e.getMessage(),true);}finally{running=false;try{flush();}catch(Exception e){logger.line("save: "+e.getMessage(),true);}}}
    private synchronized void physicsStep(float dt)throws Exception{if(sceneCache==null)sceneCache=loadScene();JSONArray a=sceneCache.optJSONArray("objects");boolean changed=false;for(int i=0;a!=null&&i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o==null)continue;if("vehicle".equals(o.optString("type"))&&o.optBoolean("vehiclePhysics",true)){double throttle=o.optDouble("throttle",0),steer=o.optDouble("steer",0),brake=Math.max(0,Math.min(1,o.optDouble("brake",0)));double speed=o.optDouble("speed",0);double max=o.optDouble("maxSpeed",18),accel=o.optDouble("acceleration",9),brakePower=o.optDouble("brakePower",16);speed+=throttle*accel*dt;speed-=Math.signum(speed)*brake*brakePower*dt;speed-=speed*.8*dt;if(Math.abs(speed)>max)speed=Math.signum(speed)*max;JSONArray rot=o.optJSONArray("rotation");if(rot==null)rot=new JSONArray().put(0).put(0).put(0);double yaw=rot.optDouble(1)+steer*speed*2.2*dt;rot.put(1,yaw);JSONArray p=o.optJSONArray("position");if(p==null)p=new JSONArray().put(0).put(0).put(0);double radians=Math.toRadians(yaw);p.put(0,p.optDouble(0)+Math.sin(radians)*speed*dt);p.put(2,p.optDouble(2)+Math.cos(radians)*speed*dt);p.put(1,Math.max(0,p.optDouble(1)));o.put("rotation",rot);o.put("position",p);o.put("speed",speed);changed=true;}if("tree".equals(o.optString("type"))&&o.optBoolean("falling",false)){double t=o.optDouble("fallTime",0)+dt;JSONArray rot=o.optJSONArray("rotation");if(rot==null)rot=new JSONArray().put(0).put(0).put(0);rot.put(2,Math.min(90,t/1.2*90));o.put("rotation",rot);o.put("fallTime",t);if(t>=1.2)o.put("visible",false);changed=true;}}if(changed)persistMaybe();}
    private void reload(Map<String,Program> programs){
        File folder=new File(projectDir,"scripts");File[] fs=folder.listFiles();if(fs==null)return;Arrays.sort(fs,Comparator.comparing(File::getName));Set<String> seen=new HashSet<>();
        for(File f:fs){if(!f.isFile()||!f.getName().endsWith(".ns"))continue;seen.add(f.getName());
            try{String src=ProjectStore.read(f);int hash=src.hashCode();Program old=programs.get(f.getName());if(old!=null&&old.modified==f.lastModified()&&old.sourceHash==hash)continue;String cls=f.getName().substring(0,f.getName().length()-3);Program p=new Parser(src,f.getName(),cls).parse();p.modified=f.lastModified();p.sourceHash=hash;programs.put(f.getName(),p);logger.line("Hot reload: "+f.getName(),false);}
            catch(ParseError e){programs.remove(f.getName());String key=f.getName()+":"+e.line+":"+e.getMessage();if(reported.add(key))logger.line(f.getName()+":"+e.line+": "+e.getMessage(),true);}
            catch(Exception e){String key=f.getName()+":"+e.getMessage();if(reported.add(key))logger.line(f.getName()+": "+e.getMessage(),true);}
        }
        Iterator<String> it=programs.keySet().iterator();while(it.hasNext())if(!seen.contains(it.next()))it.remove();
    }
    private void run(Program p,Stmt stmt,float dt){try{if(p.env==null){p.env=new Env(null);Context init=new Context(p.file,p.env,dt);for(Map.Entry<String,Expr> e:p.fields.entrySet())p.env.values.put(e.getKey(),e.getValue().eval(init));}p.env.values.put("dt",(double)dt);stmt.exec(new Context(p.file,p.env,dt));}catch(ReturnSignal ignored){}catch(RuntimeError e){String k=p.file+":"+e.line+":"+e.getMessage();if(reported.add(k))logger.line(p.file+":"+e.line+": "+e.getMessage(),true);}catch(Exception e){logger.line(p.file+": "+e.getMessage(),true);}}

    private interface Stmt { void exec(Context c)throws Exception; }
    private interface Expr { Object eval(Context c)throws Exception; }
    private static final class Context {final String file;final Env env;final float dt;int steps;Context(String f,Env e,float d){file=f;env=e;dt=d;}void step(int line){if(++steps>MAX_STEPS)throw new RuntimeError(line,"instruction budget exceeded (possible infinite loop)");}}
    private static final class Env {final Env parent;final Map<String,Object> values=new HashMap<>();Env(Env p){parent=p;}Object get(String n,int line){if(values.containsKey(n))return values.get(n);if(parent!=null)return parent.get(n,line);throw new RuntimeError(line,"unknown variable '"+n+"'");}void set(String n,Object v,int line){if(values.containsKey(n)){values.put(n,v);return;}if(parent!=null&&parent.has(n)){parent.set(n,v,line);return;}throw new RuntimeError(line,"unknown variable '"+n+"'");}boolean has(String n){return values.containsKey(n)||(parent!=null&&parent.has(n));}}
    private static final class RuntimeError extends RuntimeException {final int line;RuntimeError(int l,String m){super(m);line=l;}}
    private static final class ReturnSignal extends RuntimeException {final Object value;ReturnSignal(Object v){value=v;}}
    private static final class BreakSignal extends RuntimeException {}
    private static final class ContinueSignal extends RuntimeException {}
    private static final class Program {String file;long modified;int sourceHash;Stmt start,update;boolean started;Env env;final Map<String,Expr> fields=new LinkedHashMap<>();}
    private static final class Vec3 {double x,y,z;Vec3(double a,double b,double c){x=a;y=b;z=c;}Vec3 plus(Vec3 b){return new Vec3(x+b.x,y+b.y,z+b.z);}Vec3 mul(double s){return new Vec3(x*s,y*s,z*s);} }
    private static final class ObjectRef {final String name;ObjectRef(String n){name=n;}}

    private final class Block implements Stmt {final List<Stmt> list;final int line;Block(List<Stmt> s,int l){list=s;line=l;}public void exec(Context c)throws Exception{for(Stmt s:list){c.step(line);s.exec(c);}}}
    private final class VarStmt implements Stmt {final String name;final Expr value;final int line;VarStmt(String n,Expr e,int l){name=n;value=e;line=l;}public void exec(Context c)throws Exception{c.env.values.put(name,value==null?0.0:value.eval(c));}}
    private final class ExprStmt implements Stmt {final Expr e;final int line;ExprStmt(Expr x,int l){e=x;line=l;}public void exec(Context c)throws Exception{e.eval(c);}}
    private final class IfStmt implements Stmt {final Expr condition;final Stmt yes,no;final int line;IfStmt(Expr c,Stmt y,Stmt n,int l){condition=c;yes=y;no=n;line=l;}public void exec(Context c)throws Exception{if(truth(condition.eval(c)))yes.exec(c);else if(no!=null)no.exec(c);}}
    private final class WhileStmt implements Stmt {final Expr condition;final Stmt body;final int line;WhileStmt(Expr e,Stmt s,int l){condition=e;body=s;line=l;}public void exec(Context c)throws Exception{while(truth(condition.eval(c))){c.step(line);try{body.exec(c);}catch(ContinueSignal ignored){}catch(BreakSignal b){break;}}}}
    private final class ForStmt implements Stmt {final Stmt init,body;final Expr condition,step;final int line;ForStmt(Stmt i,Expr c,Expr s,Stmt b,int l){init=i;condition=c;step=s;body=b;line=l;}public void exec(Context c)throws Exception{Env old=c.env;Context inner=new Context(c.file,new Env(old),c.dt);if(init!=null)init.exec(inner);while(condition==null||truth(condition.eval(inner))){inner.step(line);try{body.exec(inner);}catch(ContinueSignal ignored){}catch(BreakSignal b){break;}if(step!=null)step.eval(inner);}}}
    private final class ForeachStmt implements Stmt {final String name;final Expr source;final Stmt body;final int line;ForeachStmt(String n,Expr e,Stmt b,int l){name=n;source=e;body=b;line=l;}public void exec(Context c)throws Exception{Object v=source.eval(c);if(!(v instanceof Iterable))throw new RuntimeError(line,"foreach source must be iterable");for(Object item:(Iterable<?>)v){c.step(line);Env e=new Env(c.env);e.values.put(name,item);Context inner=new Context(c.file,e,c.dt);try{body.exec(inner);}catch(ContinueSignal ignored){}catch(BreakSignal b){break;}}}}
    private final class FlowStmt implements Stmt {final int kind;FlowStmt(int k){kind=k;}public void exec(Context c){if(kind==0)throw new BreakSignal();if(kind==1)throw new ContinueSignal();throw new ReturnSignal(null);}}
    private final class ReturnStmt implements Stmt {final Expr e;ReturnStmt(Expr x){e=x;}public void exec(Context c)throws Exception{throw new ReturnSignal(e==null?null:e.eval(c));}}

    private final class Literal implements Expr {final Object v;Literal(Object x){v=x;}public Object eval(Context c){return v;}}
    private final class Name implements Expr {final String n;final int line;Name(String s,int l){n=s;line=l;}public Object eval(Context c)throws Exception{if("self".equals(n))return firstSceneObject(line);return c.env.get(n,line);}}
    private final class VecExpr implements Expr {final Expr[] e;VecExpr(Expr[] a){e=a;}public Object eval(Context c)throws Exception{return new Vec3(num(e[0].eval(c)),num(e[1].eval(c)),num(e[2].eval(c)));}}
    private final class Unary implements Expr {final String op;final Expr x;final int line;Unary(String o,Expr e,int l){op=o;x=e;line=l;}public Object eval(Context c)throws Exception{Object a=x.eval(c);if("!".equals(op))return !truth(a);if("-".equals(op))return -num(a);if("+".equals(op))return num(a);throw new RuntimeError(line,"bad unary operator");}}
    private final class Binary implements Expr {final String op;final Expr a,b;final int line;Binary(String o,Expr x,Expr y,int l){op=o;a=x;b=y;line=l;}public Object eval(Context c)throws Exception{Object x=a.eval(c);if("&&".equals(op)&&!truth(x))return false;if("||".equals(op)&&truth(x))return true;Object y=b.eval(c);switch(op){case "+":if(x instanceof String||y instanceof String)return String.valueOf(x)+y;if(x instanceof Vec3&&y instanceof Vec3)return ((Vec3)x).plus((Vec3)y);return num(x)+num(y);case "-":return num(x)-num(y);case "*":if(x instanceof Vec3)return ((Vec3)x).mul(num(y));return num(x)*num(y);case "/":if(num(y)==0)throw new RuntimeError(line,"division by zero");return num(x)/num(y);case "%":return num(x)%num(y);case "==":return equal(x,y);case "!=":return !equal(x,y);case "<":return num(x)<num(y);case ">":return num(x)>num(y);case "<=":return num(x)<=num(y);case ">=":return num(x)>=num(y);case "&&":return truth(x)&&truth(y);case "||":return truth(x)||truth(y);default:throw new RuntimeError(line,"unknown operator "+op);}}}
    private final class Assign implements Expr {final Expr target,value;final String op;final int line;Assign(Expr t,String o,Expr v,int l){target=t;op=o;value=v;line=l;}public Object eval(Context c)throws Exception{Object v=value.eval(c);if(target instanceof Name){Name n=(Name)target;Object old=null;if(!"=".equals(op))old=c.env.get(n.n,line);Object result="+=".equals(op)?add(old,v):"-=".equals(op)?num(old)-num(v):"*=".equals(op)?num(old)*num(v):v;if(c.env.has(n.n))c.env.set(n.n,result,line);else c.env.values.put(n.n,result);return result;}if(target instanceof Member){Member m=(Member)target;m.set(c,v);return v;}throw new RuntimeError(line,"invalid assignment target");}}
    private final class Member implements Expr {final Expr base;final String key;final int line;Member(Expr b,String k,int l){base=b;key=k;line=l;}public Object eval(Context c)throws Exception{Object o=base.eval(c);if(o instanceof Vec3){Vec3 v=(Vec3)o;if("x".equals(key))return v.x;if("y".equals(key))return v.y;if("z".equals(key))return v.z;}if(o instanceof ObjectRef){return objectProperty((ObjectRef)o,key);}throw new RuntimeError(line,"no property '"+key+"'");}void set(Context c,Object value)throws Exception{Object o=base.eval(c);if(o instanceof Vec3){Vec3 v=(Vec3)o;double n=num(value);if("x".equals(key))v.x=n;else if("y".equals(key))v.y=n;else if("z".equals(key))v.z=n;else throw new RuntimeError(line,"unknown vec3 field "+key);return;}if(o instanceof ObjectRef){setObjectProperty((ObjectRef)o,key,value);return;}throw new RuntimeError(line,"property is not writable");}}
    private final class Call implements Expr {final Expr target;final List<Expr> args;final int line;Call(Expr t,List<Expr>a,int l){target=t;args=a;line=l;}public Object eval(Context c)throws Exception{ArrayList<Object> vals=new ArrayList<>();for(Expr e:args)vals.add(e.eval(c));if(target instanceof Name)return function(((Name)target).n,vals,c,line);if(target instanceof Member){Member m=(Member)target;Object base=m.base.eval(c);String method=m.key;if(base instanceof ApiRef)return api(((ApiRef)base).name,method,vals,c,line);if(base instanceof ObjectRef)return objectCall((ObjectRef)base,method,vals,line);}throw new RuntimeError(line,"expression is not callable");}}
    private static final class ApiRef {final String name;ApiRef(String n){name=n;}}
    private final class ApiName implements Expr {final String name;ApiName(String n){name=n;}public Object eval(Context c){return new ApiRef(name);}}

    private Object function(String n,List<Object>a,Context c,int line)throws Exception{if("vec3".equals(n)){if(a.size()!=3)throw new RuntimeError(line,"vec3 needs 3 arguments");return new Vec3(num(a.get(0)),num(a.get(1)),num(a.get(2)));}if("Scene.Find".equals(n))return new ObjectRef(String.valueOf(a.get(0)));if("Time.Delta".equals(n))return (double)c.dt;throw new RuntimeError(line,"unknown function "+n);}
    private Object api(String api,String method,List<Object>a,Context c,int line)throws Exception{if("Scene".equals(api)&&"Find".equals(method)){if(a.isEmpty())throw new RuntimeError(line,"Scene.Find expects a name");return new ObjectRef(String.valueOf(a.get(0)));}if("Scene".equals(api)&&"Spawn".equals(method)){if(a.size()<3||!(a.get(2) instanceof Vec3))throw new RuntimeError(line,"Scene.Spawn(type,name,position) expects 3 arguments");return spawn(String.valueOf(a.get(0)),String.valueOf(a.get(1)),(Vec3)a.get(2),line);}if("Terrain".equals(api)&&"Create".equals(method)){if(a.size()<3||!(a.get(2) instanceof Vec3))throw new RuntimeError(line,"Terrain.Create(name,size,position) expects 3 arguments");ObjectRef r=spawn("terrain",String.valueOf(a.get(0)),(Vec3)a.get(2),line);JSONObject t=findObject(r.name);t.put("terrainSize",num(a.get(1)));return r;}if("Terrain".equals(api)&&"Generate".equals(method)){if(a.size()<5||!(a.get(4) instanceof Vec3))throw new RuntimeError(line,"Terrain.Generate(name,size,frequency,amplitude,position) expects 5 arguments");ObjectRef r=spawn("terrain",String.valueOf(a.get(0)),(Vec3)a.get(4),line);JSONObject t=findObject(r.name);int resolution=16;t.put("terrainSize",num(a.get(1)));t.put("heightFrequency",num(a.get(2)));t.put("heightScale",num(a.get(3)));JSONArray heights=new JSONArray();double seed=r.name.hashCode();for(int z=0;z<resolution;z++)for(int x=0;x<resolution;x++){double nx=x/(double)(resolution-1),nz=z/(double)(resolution-1);double h=(Math.sin((nx+seed)*num(a.get(2)))+Math.cos((nz-seed)*num(a.get(2)))*.7+Math.sin((nx+nz)*num(a.get(2))*1.7)*.35)/2.05;heights.put(h*num(a.get(3)));}t.put("heightmapResolution",resolution);t.put("heightmap",heights);persistMaybe();return r;}if("Terrain".equals(api)&&"SetTexture".equals(method)){if(a.size()<3||!(a.get(1) instanceof Vec3)||!(a.get(2) instanceof Vec3))throw new RuntimeError(line,"Terrain.SetTexture(name,baseColor,detailColor) expects 3 arguments");JSONObject t=findObject(String.valueOf(a.get(0)));if(t==null)throw new RuntimeError(line,"terrain not found");t.put("terrainBaseColor",vecJson((Vec3)a.get(1)));t.put("terrainDetailColor",vecJson((Vec3)a.get(2)));persistMaybe();return null;}if("Tree".equals(api)&&"Create".equals(method)){if(a.size()<2||!(a.get(1) instanceof Vec3))throw new RuntimeError(line,"Tree.Create(name,position) expects 2 arguments");ObjectRef r=spawn("tree",String.valueOf(a.get(0)),(Vec3)a.get(1),line);JSONObject t=findObject(r.name);t.put("treeHealth",3);t.put("treeHeight",3);t.put("falling",false);return r;}if("Interaction".equals(api)&&"Chop".equals(method)){if(a.size()<1)throw new RuntimeError(line,"Interaction.Chop(tree,damage) expects a tree name");JSONObject t=findObject(String.valueOf(a.get(0)));if(t==null||!"tree".equals(t.optString("type")))throw new RuntimeError(line,"tree not found");double health=t.optDouble("treeHealth",3)-(a.size()>1?num(a.get(1)):1);t.put("treeHealth",health);if(health<=0){t.put("falling",true);t.put("fallTime",0);t.put("visible",true);}persistMaybe();return health;}if("Vehicle".equals(api)&&"Create".equals(method)){if(a.size()<2||!(a.get(1) instanceof Vec3))throw new RuntimeError(line,"Vehicle.Create(name,position) expects 2 arguments");ObjectRef r=spawn("vehicle",String.valueOf(a.get(0)),(Vec3)a.get(1),line);JSONObject v=findObject(r.name);v.put("vehiclePhysics",true);v.put("maxSpeed",18);v.put("acceleration",9);v.put("brakePower",16);v.put("throttle",0);v.put("steer",0);v.put("brake",0);return r;}if("Vehicle".equals(api)&&"Configure".equals(method)){if(a.size()<4)throw new RuntimeError(line,"Vehicle.Configure(name,maxSpeed,acceleration,brakePower) expects 4 arguments");JSONObject v=findObject(String.valueOf(a.get(0)));if(v==null)throw new RuntimeError(line,"vehicle not found");v.put("maxSpeed",num(a.get(1)));v.put("acceleration",num(a.get(2)));v.put("brakePower",num(a.get(3)));persistMaybe();return null;}if("Vehicle".equals(api)&&"Control".equals(method)){if(a.size()<4)throw new RuntimeError(line,"Vehicle.Control(name,throttle,steer,brake) expects 4 arguments");JSONObject v=findObject(String.valueOf(a.get(0)));if(v==null)throw new RuntimeError(line,"vehicle not found");v.put("throttle",Math.max(-1,Math.min(1,num(a.get(1)))));v.put("steer",Math.max(-1,Math.min(1,num(a.get(2)))));v.put("brake",Math.max(0,Math.min(1,num(a.get(3)))));return null;}if("Player".equals(api)&&"Create".equals(method)){if(a.size()<2||!(a.get(1) instanceof Vec3))throw new RuntimeError(line,"Player.Create(name,position) expects 2 arguments");return spawn("player",String.valueOf(a.get(0)),(Vec3)a.get(1),line);}if("Camera".equals(api)&&"SetPosition".equals(method)){if(a.isEmpty()||!(a.get(0) instanceof Vec3))throw new RuntimeError(line,"Camera.SetPosition expects vec3");mutate("Camera","position",(Vec3)a.get(0));return null;}if("Log".equals(api)){String text=a.isEmpty()?"":String.valueOf(a.get(0));logger.line(text,"Error".equals(method));return null;}if("Time".equals(api)&&"Delta".equals(method))return (double)c.dt;if("Math".equals(api)){double x=a.isEmpty()?0:num(a.get(0));switch(method){case "Abs":return Math.abs(x);case "Sqrt":return Math.sqrt(x);case "Floor":return Math.floor(x);case "Round":return (double)Math.round(x);case "Min":return Math.min(x,num(a.get(1)));case "Max":return Math.max(x,num(a.get(1)));case "Clamp":return Math.max(num(a.get(1)),Math.min(num(a.get(2)),x));}}throw new RuntimeError(line,"unsupported API "+api+"."+method);}
    private JSONArray vecJson(Vec3 v)throws Exception{return new JSONArray().put(v.x).put(v.y).put(v.z);}
    private synchronized ObjectRef spawn(String type,String requested,Vec3 p,int line){try{if(sceneCache==null)sceneCache=loadScene();JSONArray a=sceneCache.optJSONArray("objects");if(a==null){a=new JSONArray();sceneCache.put("objects",a);}String name=requested==null||requested.trim().isEmpty()?type:requested.trim();String base=name;int n=2;while(findIn(a,name)!=null)name=base+" "+n++;JSONObject o=new JSONObject();o.put("name",name);o.put("type",type);o.put("visible",true);o.put("position",new JSONArray().put(p.x).put(p.y).put(p.z));o.put("rotation",new JSONArray().put(0).put(0).put(0));JSONArray scale=new JSONArray().put(1).put(1).put(1);if("terrain".equals(type))o.put("terrainSize",20);if("vehicle".equals(type)){o.put("vehicleWheels",4);scale=new JSONArray().put(1.8).put(.6).put(3);}o.put("scale",scale);o.put("color",new JSONArray().put(.55).put(.36).put(.96));a.put(o);persistMaybe();return new ObjectRef(name);}catch(Exception e){throw new RuntimeError(line,"cannot spawn "+type+": "+e.getMessage());}}
    private JSONObject findIn(JSONArray a,String name)throws Exception{for(int i=0;i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&name.equals(o.optString("name")))return o;}return null;}
    private Object objectCall(ObjectRef ref,String method,List<Object>a,int line)throws Exception{if("Destroy".equals(method)){deleteObject(ref.name);return null;}if("Move".equals(method)||"Rotate".equals(method)||"SetColor".equals(method)){if(a.isEmpty()||!(a.get(0) instanceof Vec3))throw new RuntimeError(line,method+" expects vec3");mutate(ref.name,method,(Vec3)a.get(0));return null;}throw new RuntimeError(line,"unsupported NovaObject method "+method);}
    private Object objectProperty(ObjectRef ref,String key)throws Exception{JSONObject o=findObject(ref.name);if(o==null)throw new RuntimeError(1,"object not found: "+ref.name);if("name".equals(key))return ref.name;JSONArray a=o.optJSONArray("position");if(a==null)a=new JSONArray().put(0).put(0).put(0);if("position".equals(key))return new Vec3(a.optDouble(0),a.optDouble(1),a.optDouble(2));if("visible".equals(key))return o.optBoolean("visible",true);throw new RuntimeError(1,"unsupported property "+key);}
    private void setObjectProperty(ObjectRef ref,String key,Object value)throws Exception{if("position".equals(key)&&value instanceof Vec3){mutate(ref.name,"position",(Vec3)value);return;}if("visible".equals(key)){JSONObject root=loadScene();JSONArray a=root.optJSONArray("objects");for(int i=0;a!=null&&i<a.length();i++){JSONObject o=a.getJSONObject(i);if(ref.name.equals(o.optString("name"))){o.put("visible",truth(value));ProjectStore.write(sceneFile,root.toString(2));logger.changed();return;}}}throw new RuntimeError(1,"property not supported for assignment: "+key);}
    private synchronized JSONObject loadScene()throws Exception{return new JSONObject(ProjectStore.read(sceneFile));}
    private ObjectRef firstSceneObject(int line)throws Exception{JSONObject root=sceneCache!=null?sceneCache:loadScene();JSONArray arr=root.optJSONArray("objects");for(int i=0;arr!=null&&i<arr.length();i++){JSONObject o=arr.optJSONObject(i);if(o!=null&&o.optBoolean("visible",true)&&!"camera".equals(o.optString("type"))&&!"light".equals(o.optString("type")))return new ObjectRef(o.optString("name"));}throw new RuntimeError(line,"self requires a visible scene object");}
    private synchronized JSONObject findObject(String name)throws Exception{JSONObject root=sceneCache!=null?sceneCache:loadScene();JSONArray a=root.optJSONArray("objects");for(int i=0;a!=null&&i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&name.equals(o.optString("name")))return o;}return null;}
    private synchronized void mutate(String name,String op,Vec3 v)throws Exception{if(sceneCache==null)sceneCache=loadScene();JSONArray a=sceneCache.optJSONArray("objects");JSONObject target=null;for(int i=0;a!=null&&i<a.length();i++){JSONObject o=a.optJSONObject(i);if(o!=null&&(name==null||name.isEmpty()||name.equals(o.optString("name")))){target=o;break;}}if(target==null)throw new RuntimeError(1,"object not found: "+name);String key="position";if("Rotate".equals(op))key="rotation";if("SetColor".equals(op))key="color";JSONArray vec=target.optJSONArray(key);if(vec==null)vec=new JSONArray().put(0).put(0).put(0);double[] values={v.x,v.y,v.z};for(int i=0;i<3;i++)vec.put(i,("Move".equals(op)||"Rotate".equals(op))?vec.optDouble(i)+values[i]:values[i]);target.put(key,vec);persistMaybe();}
    private synchronized void deleteObject(String name)throws Exception{JSONObject root=loadScene();JSONArray a=root.optJSONArray("objects");for(int i=0;a!=null&&i<a.length();i++)if(name.equals(a.getJSONObject(i).optString("name"))){a.remove(i);ProjectStore.write(sceneFile,root.toString(2));sceneCache=root;logger.changed();return;}}
    private void persistMaybe()throws Exception{long now=System.nanoTime();if(now-lastPersist>120000000L){ProjectStore.write(sceneFile,sceneCache.toString(2));lastPersist=now;logger.changed();}}
    private synchronized void flush()throws Exception{if(sceneCache!=null){ProjectStore.write(sceneFile,sceneCache.toString(2));logger.changed();}}
    private static Object add(Object a,Object b){if(a instanceof String||b instanceof String)return String.valueOf(a)+b;if(a instanceof Vec3&&b instanceof Vec3)return ((Vec3)a).plus((Vec3)b);return num(a)+num(b);}
    private static double num(Object x){if(x instanceof Number)return ((Number)x).doubleValue();throw new RuntimeError(1,"expected number, got "+x);}
    private static boolean truth(Object x){if(x==null)return false;if(x instanceof Boolean)return (Boolean)x;if(x instanceof Number)return ((Number)x).doubleValue()!=0;if(x instanceof String)return !((String)x).isEmpty();return true;}
    private static boolean equal(Object a,Object b){if(a instanceof Number&&b instanceof Number)return Double.compare(num(a),num(b))==0;return Objects.equals(a,b);}

    private static final class Token {final String text;final int line;final int type;Token(String t,int l,int k){text=t;line=l;type=k;}}
    private static final class ParseError extends RuntimeException {final int line;ParseError(int l,String m){super(m);line=l;}}
    private final class Parser {
        final String file,expectedClass;final ArrayList<Token> ts=new ArrayList<>();int at=0;
        Parser(String src,String f,String cls){file=f;expectedClass=cls;lex(src);}
        Program parse(){Program p=new Program();p.file=file;if(!match("class"))throw error(peek(),"expected class declaration");Token name=take();if(!name.text.equals(expectedClass))throw error(name,"class name must match file: "+expectedClass);if(match(":")){if(!match("Script"))throw error(peek(),"expected Script base class");}expect("{");while(!check("}")&&!end()){if(match("public")||match("private")||match("static"))continue;if(typeWord(peek().text)){Token type=take();Token methodName=take();if(check("(")){advance();skipMethodHeader();expect("{");Block body=blockAfterOpen(previous().line);if(methodName.text.equals("OnStart"))p.start=body;else if(methodName.text.equals("OnUpdate"))p.update=body;else if(methodName.text.equals("OnDestroy")){} }else{if(match("=")){Expr init=expression();p.fields.put(methodName.text,init);expect(";");}else{p.fields.put(methodName.text,new Literal(defaultFor(type.text)));expect(";");}}}else advance();}expect("}");return p;}
        Object defaultFor(String type){if("bool".equals(type))return false;if("string".equals(type))return "";if("vec3".equals(type))return new Vec3(0,0,0);return 0.0;}
        void skipMethodHeader(){int depth=1;while(!end()&&depth>0){if(match("("))depth++;else if(match(")"))depth--;else advance();}}
        Block blockAfterOpen(int line){ArrayList<Stmt> list=new ArrayList<>();while(!check("}")&&!end())list.add(statement());expect("}");return new Block(list,line);}
        Stmt statement(){Token t=peek();if(match("{"))return blockAfterOpen(t.line);if(match("if")){expect("(");Expr c=expression();expect(")");Stmt yes=statement(),no=null;if(match("else"))no=statement();return new IfStmt(c,yes,no,t.line);}if(match("while")){expect("(");Expr c=expression();expect(")");return new WhileStmt(c,statement(),t.line);}if(match("for")){expect("(");Stmt init=null;if(!check(";")){if(typeWord(peek().text)){take();Token nm=take();Expr v=match("=")?expression():null;init=new VarStmt(nm.text,v,nm.line);}else if(match("var")){Token nm=take();Expr v=match("=")?expression():null;init=new VarStmt(nm.text,v,nm.line);}else init=new ExprStmt(expression(),peek().line);}expect(";");Expr cond=check(";")?null:expression();expect(";");Expr step=check(")")?null:expression();expect(")");return new ForStmt(init,cond,step,statement(),t.line);}if(match("foreach")){expect("(");match("var");Token nm=take();expect("in");Expr src=expression();expect(")");return new ForeachStmt(nm.text,src,statement(),t.line);}if(match("break")){expect(";");return new FlowStmt(0);}if(match("continue")){expect(";");return new FlowStmt(1);}if(match("return")){Expr e=check(";")?null:expression();expect(";");return new ReturnStmt(e);}if(typeWord(peek().text)||match("var")){if(!previous().text.equals("var"))take();Token nm=take();Expr e=match("=")?expression():null;expect(";");return new VarStmt(nm.text,e,nm.line);}Expr e=expression();expect(";");return new ExprStmt(e,t.line);}
        Expr expression(){return assignment();}Expr assignment(){Expr e=or();if(match("=","+=","-=","*=")){Token op=previous();return new Assign(e,op.text,assignment(),op.line);}return e;}Expr or(){Expr e=and();while(match("||"))e=new Binary(previous().text,e,and(),previous().line);return e;}Expr and(){Expr e=equality();while(match("&&"))e=new Binary(previous().text,e,equality(),previous().line);return e;}Expr equality(){Expr e=compare();while(match("==","!="))e=new Binary(previous().text,e,compare(),previous().line);return e;}Expr compare(){Expr e=term();while(match("<",">","<=",">="))e=new Binary(previous().text,e,term(),previous().line);return e;}Expr term(){Expr e=factor();while(match("+","-"))e=new Binary(previous().text,e,factor(),previous().line);return e;}Expr factor(){Expr e=unary();while(match("*","/","%"))e=new Binary(previous().text,e,unary(),previous().line);return e;}Expr unary(){if(match("!","-","+"))return new Unary(previous().text,unary(),previous().line);return postfix();}
        Expr postfix(){Expr e=primary();while(true){if(match(".")){Token n=take();if(check("(")){advance();e=new Call(new Member(e,n.text,n.line),arguments(),n.line);}else e=new Member(e,n.text,n.line);}else if(match("(")){e=new Call(e,arguments(),previous().line);}else if(match("++","--")){Token op=previous();e=new Assign(e,op.text.startsWith("+")?"+=":"-=",new Literal(1.0),op.line);}else break;}return e;}
        List<Expr> arguments(){ArrayList<Expr>a=new ArrayList<>();if(!check(")")){do{a.add(expression());}while(match(","));}expect(")");return a;}
        Expr primary(){Token t=advance();if(t.text.equals("true"))return new Literal(true);if(t.text.equals("false"))return new Literal(false);if(t.text.equals("null"))return new Literal(null);if(t.type==2)return new Literal(Double.parseDouble(t.text));if(t.type==3)return new Literal(t.text.substring(1,t.text.length()-1).replace("\\n","\n").replace("\\\"","\""));if(t.text.equals("(")){Expr e=expression();expect(")");return e;}if(t.text.equals("vec3")){expect("(");List<Expr>a=arguments();if(a.size()!=3)throw error(t,"vec3 needs 3 values");return new VecExpr(a.toArray(new Expr[0]));}if(t.type==1){if(t.text.equals("Log")||t.text.equals("Time")||t.text.equals("Math")||t.text.equals("Scene")||t.text.equals("Terrain")||t.text.equals("Vehicle")||t.text.equals("Player")||t.text.equals("Camera")||t.text.equals("Tree")||t.text.equals("Interaction"))return new ApiName(t.text);return new Name(t.text,t.line);}throw error(t,"expected expression");}
        void lex(String s){int i=0,line=1;while(i<s.length()){char c=s.charAt(i);if(Character.isWhitespace(c)){if(c=='\n')line++;i++;continue;}if(c=='/'&&i+1<s.length()&&s.charAt(i+1)=='/'){while(i<s.length()&&s.charAt(i)!='\n')i++;continue;}if(c=='/'&&i+1<s.length()&&s.charAt(i+1)=='*'){i+=2;while(i+1<s.length()&&!(s.charAt(i)=='*'&&s.charAt(i+1)=='/')){if(s.charAt(i)=='\n')line++;i++;}i=Math.min(s.length(),i+2);continue;}int start=i;if(Character.isLetter(c)||c=='_'){i++;while(i<s.length()&&(Character.isLetterOrDigit(s.charAt(i))||s.charAt(i)=='_'))i++;ts.add(new Token(s.substring(start,i),line,1));continue;}if(Character.isDigit(c)||(c=='.'&&i+1<s.length()&&Character.isDigit(s.charAt(i+1)))){i++;while(i<s.length()&&(Character.isDigit(s.charAt(i))||s.charAt(i)=='.'))i++;if(i<s.length()&&(s.charAt(i)=='f'||s.charAt(i)=='F'))i++;ts.add(new Token(s.substring(start,i).replaceAll("[fF]$",""),line,2));continue;}if(c=='"'||c=='\''){char q=c;i++;while(i<s.length()&&s.charAt(i)!=q){if(s.charAt(i)=='\\'&&i+1<s.length())i++;if(s.charAt(i)=='\n')line++;i++;}if(i>=s.length())throw new ParseError(line,"unterminated string");i++;ts.add(new Token(s.substring(start,i),line,3));continue;}String two=i+1<s.length()?s.substring(i,i+2):"";if(Arrays.asList("==","!=","<=",">=","&&","||","+=","-=","*=","++","--").contains(two)){ts.add(new Token(two,line,0));i+=2;}else{ts.add(new Token(String.valueOf(c),line,0));i++;}}ts.add(new Token("<eof>",line,-1));}
        void skipToSemi(){while(!end()&&!match(";"))advance();}boolean typeWord(String s){return Arrays.asList("void","int","float","double","bool","string","vec2","vec3","vec4","NovaObject","Widget","List").contains(s);}boolean match(String...s){for(String x:s)if(check(x)){advance();return true;}return false;}boolean check(String s){return peek().text.equals(s);}Token expect(String s){if(check(s))return advance();throw error(peek(),"expected '"+s+"'");}Token take(){if(end())throw error(peek(),"unexpected end");return advance();}Token peek(){return ts.get(Math.min(at,ts.size()-1));}Token previous(){return ts.get(Math.max(0,at-1));}Token advance(){if(!end())at++;return previous();}boolean end(){return peek().type==-1;}ParseError error(Token t,String m){return new ParseError(t.line,m);}
    }
}
